L["TIP_BROKER_SHARE_ALL"] = "Publishes the blocks chosen below as DataBroker objects, while Tessera keeps showing its own blocks."
L["BROKER_BLOCK"] = "Block"
L["TIP_BROKER_BLOCK"] = "The block whose sharing and settings are shown here. Shared blocks are marked."
